const пауза = (мс, значение) => new Promise(выполнить => setTimeout(() => выполнить(значение), мс));

Promise.any([
  Promise.reject(new Error("первый источник недоступен")),
  пауза(20, "ответ второго источника"),
  пауза(50, "ответ третьего источника"),
]).then(результат => console.log(результат));
